/**
 * @file fp_to_int_test.cpp
 * @brief fcvt.{w,wu,l,lu}.{s,d} at NaN, infinities, the type bounds and in
 *        every rounding mode, on all five models (known_issues 73).
 *
 * The RISC-V spec: round the exact value in the instruction's mode; NaN and
 * +inf give the type's largest value, -inf its smallest (0 for unsigned); a
 * rounded value out of range saturates; 32-bit results are sign-extended.
 * Inputs: NaNs, +-inf, +-2^31, 2^32, +-2^63, 2^64 and their neighbours in
 * each format, -0.0, negatives to unsigned types, in-range ties, and (for .d)
 * values that round across a 32-bit bound. RMM is asserted only off ties
 * (113). Flags are not asserted (72).
 *
 * One program per (mnemonic, mode); each conversion is stored to scratch.
 * Expected dwords come from ~/atlas-verify/e4/gen_fcvt_int.py.
 */
