class FpToInt : public testing::TestWithParam<IsaParam>
{
};

INSTANTIATE_TEST_SUITE_P(AllModels, FpToInt, testing::ValuesIn(isaParams(kCases, allModels())),
                         [](const testing::TestParamInfo<IsaParam> &info)
                         { return isaParamName(kCases, info.param); });

TEST_P(FpToInt, ConversionsMatchTheSpecTable)
{
    QTemporaryDir dir;
    ASSERT_TRUE(dir.isValid());
    expectIsaCase(kCases[GetParam().index], GetParam().model, dir);
}
